const PRICES=[1.79,2.19,2.59],SALES=['DTC Online','Retail/Grocery','Gym & Office'];
const money=(v,d=2)=>Number(v).toLocaleString('en-GB',{style:'currency',currency:'EUR',minimumFractionDigits:d,maximumFractionDigits:d}),number=(v,d=0)=>Number(v).toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}),pct=v=>`${number(v,1)}%`,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,state={price:2.19,sales:'Retail/Grocery',marketing:'Referral / Subscription',budget:'500'};
const HEADER_ART=`<svg class="header-art" viewBox="0 0 260 150" aria-hidden="true" focusable="false"><g fill="none" stroke="currentColor"><rect class="can-body" x="82" y="24" width="62" height="108" rx="18"/><path d="M94 29c11-5 27-5 38 0M101 47h24M113 47v62"/><circle cx="175" cy="35" r="9"/><circle cx="201" cy="65" r="5"/><circle cx="169" cy="91" r="4"/><path class="spark" d="M211 16v18M202 25h18M192 100v24M180 112h24"/></g></svg>`;
const LEAF_ART=`<svg class="leaf-art" viewBox="0 0 120 82" aria-hidden="true" focusable="false"><g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="M18 69C42 44 64 29 103 15M41 51C28 49 21 40 20 27c15-2 27 4 32 15M64 36c-2-14 6-25 21-31 6 15 1 29-12 37M80 27c10 1 18 8 22 20-12 4-22 1-30-9"/></g></svg>`;
const median=a=>{const x=[...a].sort((m,n)=>m-n);return x.length?(x[Math.floor((x.length-1)/2)]+x[Math.floor(x.length/2)])/2:NaN};
const row=(p,c)=>data?.prices?.find(x=>x.price_eur===p&&x.channel===c),mkt=c=>data?.marketing?.find(x=>x.channel===c);
function estimate(p,c){const r=row(p,c),base=row(2.19,c),economics=(data?.economics||[]).some(x=>x.channel===c),reference=median((data?.historical?.countries||[]).map(x=>x.monthlyUnits));if(!r||!base||!economics||!Number.isFinite(reference)||!Number.isFinite(r.unit_contribution_eur)||!Number.isFinite(r.estimated_acceptance_pct_of_survey)||!Number.isFinite(r.net_price_to_lumen_eur))return null;const factor=r.estimated_acceptance_pct_of_survey/base.estimated_acceptance_pct_of_survey,units=reference*.1*factor;return{...r,units,monthlyContribution:units*r.unit_contribution_eur,annualContribution:units*r.unit_contribution_eur*12}}
function budgetInfo(){const raw=String(state.budget??'').trim(),value=Number(raw);return{raw,value,valid:raw!==''&&Number.isFinite(value)&&value>=0}}
function rankings(sales,marketing){const m=mkt(marketing);if(!m||!Number.isFinite(m.cac)||m.cac<=0)return[];return PRICES.map(price=>{const y=estimate(price,sales);if(!y||!Number.isFinite(y.unit_contribution_eur)||y.unit_contribution_eur<=0)return null;return{price,y,payback:m.cac/(y.unit_contribution_eur*12)}}).filter(Boolean).sort((a,b)=>a.payback-b.payback).map((item,index)=>{const reason=item.price===1.79?'It has the strongest acceptance, but its thinner contribution slows acquisition-cost recovery.':item.price===2.19?'It balances acceptance with contribution, giving a middle-ground payback for this channel mix.':'It has the strongest contribution and fastest payback, but its lower acceptance may limit volume.';return{...item,rank:index+1,reason:`${reason} Payback proxy: ${number(item.payback,1)} months.`}})}
function message(text){return `<div class="inline-message" role="status">${esc(text)}</div>`}
function decorate(){const header=document.querySelector('.shell header'),nuance=document.querySelector('.nuance');if(header&&!header.querySelector('.header-art'))header.insertAdjacentHTML('beforeend',HEADER_ART);if(nuance&&!nuance.querySelector('.leaf-art'))nuance.insertAdjacentHTML('beforeend',LEAF_ART)}
const ANIMATED_VALUES='.metric-grid strong,.price-card b,.big-number,.budget-row strong';
function valueParts(text){const match=String(text).match(/-?[\d,.]+/);if(!match)return null;const raw=match[0],value=Number(raw.replaceAll(',',''));if(!Number.isFinite(value))return null;const dot=raw.indexOf('.'),decimals=dot<0?0:raw.length-dot-1;return{value,decimals,prefix:text.slice(0,match.index),suffix:text.slice(match.index+raw.length)}}
function animateValue(element,fromText){const targetText=element.textContent,from=valueParts(fromText),to=valueParts(targetText);if(!from||!to||from.value===to.value)return;const duration=480,start=performance.now();element.textContent=fromText;element.classList.add('is-counting');const tick=now=>{const progress=Math.min(1,(now-start)/duration),eased=progress<.5?2*progress*progress:1-Math.pow(-2*progress+2,2)/2,value=from.value+(to.value-from.value)*eased;element.textContent=`${to.prefix}${value.toLocaleString('en-GB',{minimumFractionDigits:to.decimals,maximumFractionDigits:to.decimals})}${to.suffix}`;if(progress<1)requestAnimationFrame(tick);else{element.textContent=targetText;element.classList.remove('is-counting')}};requestAnimationFrame(tick)}
function animateDashboard(oldRoot){if(!oldRoot)return;const oldValues=[...oldRoot.querySelectorAll(ANIMATED_VALUES)].map(x=>x.textContent),newValues=[...document.querySelectorAll(ANIMATED_VALUES)];newValues.forEach((element,index)=>oldValues[index]!==undefined&&animateValue(element,oldValues[index]));document.querySelectorAll('.card').forEach(card=>card.classList.add('is-updating'))}
function update(){const oldRoot=document.querySelector('#app').firstElementChild?.cloneNode(true);app();animateDashboard(oldRoot)}
function app(){const x=estimate(state.price,state.sales),m=mkt(state.marketing),b=budgetInfo(),ranked=rankings(state.sales,state.marketing),annualBudget=b.valid?b.value*12:0,after=x&&b.valid?x.annualContribution-annualBudget:0;document.querySelector('#app').innerHTML=`<div class="shell"><header><div><div class="eyebrow">LUMEN / GERMANY LAUNCH</div><h1>Scenario dashboard</h1><p class="lede">Make the price × sales channel × acquisition channel trade-off visible.</p></div><div class="status">CASE EVIDENCE · LOCAL CALCULATIONS</div></header><div class="notice"><strong>Recommended starting point: €2.19</strong><span>Balanced acceptance and contribution. Change the controls to test the CFO payback case against the premium option.</span></div><section class="controls-panel"><div><label>Launch price<select id="price">${PRICES.map(p=>`<option value="${p}" ${p===state.price?'selected':''}>${money(p)}${p===2.19?' · recommended':''}</option>`).join('')}</select></label><div class="price-context">${state.price===1.79?'Highest acceptance, thinnest contribution.':state.price===2.19?'Balanced acceptance / contribution trade-off.':'Highest contribution, acceptance nearly halves.'}</div></div><div><label>Sales channel<select id="sales">${SALES.map(s=>`<option ${s===state.sales?'selected':''}>${esc(s)}</option>`).join('')}</select></label><div class="price-context">Retail/Grocery is most preferred overall; Gym & Office and DTC fit higher-intent segments.</div></div><div><label>Marketing / acquisition channel<select id="marketing">${(data.marketing||[]).map(y=>`<option ${y.channel===state.marketing?'selected':''}>${esc(y.channel)}</option>`).join('')}</select></label><div class="price-context">This controls CAC/LTV only; it does not change sales-channel contribution.</div></div><div><label>Monthly acquisition budget<input id="budget" type="text" inputmode="decimal" value="${esc(b.raw)}"></label><div class="price-context">Enter zero or a positive number to see payback.</div></div></section><section class="nuance"><strong>Segment nuance</strong><span>Urban Wellness Professionals show the strongest intent and lowest price sensitivity, supporting premium testing. Students are highly price-sensitive, so €2.59 risks volume. The selector is evidence-led—not a hidden universal winner.</span></section><section class="dashboard"><div class="card primary-card"><div class="card-head"><div><div class="eyebrow">COMMERCIAL ECONOMICS</div><h2>${money(state.price)} · ${esc(state.sales)}</h2></div><span class="pill">Sales channel</span></div>${x?`<div class="metric-grid"><div><span>Acceptance</span><strong>${pct(x.estimated_acceptance_pct_of_survey)}</strong><small>of tested survey</small></div><div><span>Net to LUMEN</span><strong>${money(x.net_price_to_lumen_eur)}</strong><small>per can</small></div><div><span>Unit contribution</span><strong>${money(x.unit_contribution_eur)}</strong><small>${pct(x.contribution_margin_pct)} margin</small></div><div><span>Modeled monthly contribution</span><strong>${money(x.monthlyContribution,0)}</strong><small>conditional estimate</small></div></div><p class="definition">Contribution is driven by price-test and sales-channel economics. It is intentionally separate from acquisition ROI.</p>`:message('No data for this price and sales-channel combination.')}</div><div class="card"><div class="card-head"><div><div class="eyebrow">ACQUISITION ECONOMICS</div><h2>${esc(state.marketing)}</h2></div><span class="pill green">Marketing channel</span></div>${!m?message('No data for this marketing channel.'):!b.valid?message(b.raw===''?'Enter a budget to see payback.':Number.isNaN(b.value)?'Enter a numeric budget to see payback.':'Enter a non-negative budget to see payback.'):!x?message('No data for this price and sales-channel combination.'):m.cac<=0?message('No valid CAC data for this marketing channel.'): `<div class="metric-grid two"><div><span>CAC</span><strong>${money(m.cac)}</strong><small>historical weighted</small></div><div><span>Estimated LTV</span><strong>${money(m.ltv)}</strong><small>historical weighted</small></div><div><span>LTV : CAC</span><strong>${number(m.ltv/m.cac,1)}×</strong><small>not blended with margin</small></div><div><span>Payback proxy</span><strong>${number(m.cac/(x.unit_contribution_eur*12),1)} mo</strong><small>12 cans/customer/month</small></div></div><p class="definition">CAC/LTV uses the selected marketing channel. Payback is an illustrative contribution recovery proxy, not a validated German forecast.</p>`}</div></section><section class="card comparison"><div class="card-head"><div><div class="eyebrow">VISIBLE PRICE TRADE-OFF</div><h2>All three candidates · ${esc(state.sales)}</h2></div><span class="pill">Ranked by fastest payback</span></div>${ranked.length===3?`<div class="compare-grid">${ranked.map(({price,y,rank,reason})=>`<button class="price-card ${price===2.19?'recommended':''} ${price===state.price?'selected':''}" data-p="${price}"><span class="rank">${rank}${rank===1?'st':rank===2?'nd':'rd'} · ${rank===1?'fastest payback':rank===2?'next fastest':'slowest payback'}</span><span class="price">${money(price)}</span><span class="tagline">${price===1.79?'Volume-led':price===2.19?'Balanced':'Premium-led'}</span><div><b>${pct(y.estimated_acceptance_pct_of_survey)}</b><small>acceptance</small></div><div><b>${money(y.unit_contribution_eur)}</b><small>contribution / can</small></div><div><b>${money(y.net_price_to_lumen_eur)}</b><small>net / can</small></div><p class="why">${esc(reason)}</p></button>`).join('')}</div>`:message('No data for all three prices in this sales channel.')}<p class="definition">Rank order updates with the selected sales and marketing channels; all three candidates remain visible when data is available.</p></section><section class="bottom-grid"><div class="card"><div class="eyebrow">ESTIMATE BASIS</div><h2>German launch volume</h2>${x?`<p class="big-number">${number(x.units)} <small>conditional units / month</small></p>`:message('No volume estimate available for this combination.')}<p>Uses the median monthly units from deduplicated NL/DK/SE history, 10% deployment, and tested acceptance relative to €2.19.</p><div class="flag">⚑ German figures are estimates derived from NL/DK/SE data. No German sales history exists.</div><p class="source">Historical audit: ${number(data.audit.historicalRowsRaw)} raw rows → ${number(data.audit.historicalRowsUnique)} unique rows; ${data.audit.duplicatesRemoved} duplicate keys removed.</p></div><div class="card"><div class="eyebrow">BUDGET VIEW</div><h2>Selected acquisition budget</h2>${!b.valid?message(b.raw===''?'Enter a budget to see the budget view.':Number.isNaN(b.value)?'Enter a numeric budget to see the budget view.':'Enter a non-negative budget to see the budget view.'):!x?message('No data for this price and sales-channel combination.'): `<div class="budget-row"><span>Annual marketing spend</span><strong>${money(annualBudget,0)}</strong></div><div class="budget-row"><span>Annual contribution before marketing</span><strong>${money(x.annualContribution,0)}</strong></div><div class="budget-row total"><span>Annual contribution after marketing</span><strong class="${after>=0?'positive':'negative'}">${money(after,0)}</strong></div>`}<p class="definition">Commercial contribution and marketing spend remain separate line items.</p></div></section><footer>Aggregated data only. Customer name/email fields are never loaded. No external API or API key.</footer></div>`;bind()}
function bind(){decorate();document.querySelector('#price').onchange=e=>{state.price=Number(e.target.value);update()};document.querySelector('#sales').onchange=e=>{state.sales=e.target.value;update()};document.querySelector('#marketing').onchange=e=>{state.marketing=e.target.value;update()};document.querySelector('#budget').oninput=e=>{state.budget=e.target.value;update()};document.querySelectorAll('[data-p]').forEach(e=>e.onclick=()=>{state.price=Number(e.dataset.p);update()})}
fetch('/case-data.json').then(r=>r.json()).then(d=>{data=d;app()}).catch(e=>{document.querySelector('#app').innerHTML=`<main class="loading"><h1>Unable to load case data</h1><p>${esc(e.message)}</p></main>`});
